CREATE TABLE schema_migrations(version integer PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id text PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles(name text PRIMARY KEY CHECK(name IN ('viewer','operator','administrator')));
INSERT INTO roles VALUES ('viewer'),('operator'),('administrator');
CREATE TABLE user_roles(user_id text REFERENCES users ON DELETE CASCADE, role text REFERENCES roles, PRIMARY KEY(user_id,role));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workers(id text PRIMARY KEY, config jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true, version text NOT NULL DEFAULT '', session_id text NOT NULL DEFAULT '', last_heartbeat timestamptz, active_downloads jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE revoked_certificates(serial text PRIMARY KEY, revoked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE worker_metrics(worker_id text REFERENCES workers ON DELETE CASCADE, measured_at timestamptz NOT NULL, data jsonb NOT NULL, PRIMARY KEY(worker_id,measured_at));
CREATE TABLE jobs(id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users, run_id text NOT NULL, state text NOT NULL CHECK(state IN ('created','validating','running','pausing','paused','stopping','stopped','completed','failed')), range_start numeric(20,0) NOT NULL CHECK(range_start>=0 AND range_start<=18446744073709551615), range_end numeric(20,0) CHECK(range_end>=range_start AND range_end<=18446744073709551615), frontier numeric(20,0), config jsonb NOT NULL, config_version bigint NOT NULL DEFAULT 1, reason text NOT NULL DEFAULT '', state_since timestamptz NOT NULL DEFAULT now(), no_workers_since timestamptz, started_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE job_access(job_id text REFERENCES jobs ON DELETE CASCADE, user_id text REFERENCES users ON DELETE CASCADE, permission text NOT NULL CHECK(permission IN ('view','manage')), PRIMARY KEY(job_id,user_id));
CREATE TABLE job_workers(job_id text REFERENCES jobs ON DELETE CASCADE, worker_id text REFERENCES workers, PRIMARY KEY(job_id,worker_id));
CREATE TABLE range_chunks(id text PRIMARY KEY, job_id text NOT NULL REFERENCES jobs ON DELETE CASCADE, range_start numeric(20,0) NOT NULL, range_end numeric(20,0) NOT NULL, next_id numeric(20,0), status text NOT NULL CHECK(status IN ('pending','leased','completed')), leased_by text REFERENCES workers, lease_expires_at timestamptz, attempt_id text NOT NULL DEFAULT '', attempt bigint NOT NULL DEFAULT 0, run_id text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,range_start,range_end), CHECK(range_start>=0 AND range_end>=range_start AND range_end<=18446744073709551615));
CREATE INDEX chunks_queue ON range_chunks(job_id,status,range_start);
CREATE INDEX chunks_expiry ON range_chunks(lease_expires_at) WHERE status='leased';
CREATE TABLE media_metadata(id text PRIMARY KEY, source_id text NOT NULL, external_id numeric(20,0) NOT NULL, canonical_id text NOT NULL, title text NOT NULL, page_url text NOT NULL, data jsonb NOT NULL, protected_url bytea, accepted_file_id text, found_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,external_id), UNIQUE(source_id,canonical_id));
CREATE TABLE items(job_id text REFERENCES jobs ON DELETE CASCADE, external_id numeric(20,0) NOT NULL CHECK(external_id>=0 AND external_id<=18446744073709551615), run_id text NOT NULL, chunk_id text NOT NULL REFERENCES range_chunks, attempt_id text NOT NULL, status text NOT NULL CHECK(status IN ('pending','checking','not_found','found','download_queued','downloading','completed','skipped','forbidden','rate_limited','retry_wait','failed','cancelled')), final boolean NOT NULL DEFAULT false, error_code text NOT NULL DEFAULT '', media_id text REFERENCES media_metadata, data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(job_id,external_id));
CREATE INDEX items_status ON items(job_id,status,external_id);
CREATE TABLE downloads(id text PRIMARY KEY, job_id text NOT NULL, external_id numeric(20,0) NOT NULL, worker_id text NOT NULL REFERENCES workers, attempt_id text NOT NULL, stage_id text NOT NULL, media_id text NOT NULL REFERENCES media_metadata, state text NOT NULL, size_bytes numeric(20,0) NOT NULL DEFAULT 0, offset_bytes numeric(20,0) NOT NULL DEFAULT 0, etag text NOT NULL DEFAULT '', checksum text NOT NULL DEFAULT '', retry_at timestamptz, error_code text NOT NULL DEFAULT '', FOREIGN KEY(job_id,external_id) REFERENCES items, UNIQUE(worker_id,attempt_id,stage_id));
CREATE INDEX downloads_retry ON downloads(retry_at);
CREATE TABLE storage_reservations(download_id text PRIMARY KEY REFERENCES downloads, attempt_id text NOT NULL, bytes numeric(20,0) NOT NULL CHECK(bytes>=0), expires_at timestamptz NOT NULL);
CREATE TABLE publications(id text PRIMARY KEY, download_id text UNIQUE NOT NULL REFERENCES downloads, job_id text NOT NULL REFERENCES jobs, chunk_id text NOT NULL REFERENCES range_chunks, run_id text NOT NULL, attempt_id text NOT NULL, state text NOT NULL CHECK(state IN ('verifying','ready','failed','orphan')), expected_size numeric(20,0) NOT NULL, expected_checksum text NOT NULL, relative_path text NOT NULL UNIQUE, error_code text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE files(id text PRIMARY KEY, download_id text NOT NULL REFERENCES downloads, media_id text NOT NULL REFERENCES media_metadata, publication_id text NOT NULL UNIQUE REFERENCES publications, storage_path text NOT NULL UNIQUE, size_bytes numeric(20,0) NOT NULL, checksum text NOT NULL, mime_type text NOT NULL, ready boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(download_id,storage_path));
CREATE UNIQUE INDEX one_ready_media ON files(media_id) WHERE ready;
ALTER TABLE media_metadata ADD CONSTRAINT accepted_file_fk FOREIGN KEY(accepted_file_id) REFERENCES files;
CREATE TABLE events(id bigserial PRIMARY KEY, timestamp timestamptz NOT NULL DEFAULT now(), component text NOT NULL, job_id text REFERENCES jobs, worker_id text REFERENCES workers, chunk_id text, attempt_id text, external_id numeric(20,0), operation text NOT NULL, result text NOT NULL, error_code text NOT NULL DEFAULT '', data jsonb NOT NULL DEFAULT '{}');
CREATE INDEX events_search ON events(job_id,timestamp DESC);
CREATE INDEX events_worker ON events(worker_id,timestamp DESC);
CREATE TABLE audit_log(id bigserial PRIMARY KEY, timestamp timestamptz NOT NULL DEFAULT now(), actor_id text NOT NULL, action text NOT NULL, object_id text NOT NULL, request_id text NOT NULL, context jsonb NOT NULL DEFAULT '{}');
CREATE TABLE idempotency_keys(actor_id text NOT NULL, operation text NOT NULL, key text NOT NULL, body_hash text NOT NULL, status_code integer NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,operation,key));
CREATE TABLE coordinator_epochs(id text PRIMARY KEY, active boolean NOT NULL DEFAULT true, lease_expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_epoch ON coordinator_epochs(active) WHERE active;
CREATE TABLE ssh_sessions(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, worker_id text NOT NULL REFERENCES workers, ticket_hash text NOT NULL UNIQUE, used boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE worker_actions(id text PRIMARY KEY, worker_id text NOT NULL REFERENCES workers, actor_id text NOT NULL REFERENCES users, action text NOT NULL, state text NOT NULL, error_code text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
